mapper.select:
select fecha_cita, case when count(*)>=2 and count(*) <4 then 2 when count(*)=4  then 3 end as Estatus  
	FROM (select  distinct fecha_cita, id_horario from  agenda_ovie.solicitudes where status=2 and EXTRACT (Mon FROM  fecha_cita) = #{month} and EXTRACT(year FROM  fecha_cita) = #{year} )
	a group by fecha_cita having count(*)>=2 union all select fecha_cita,5  from agenda_ovie.dia_inhabil where EXTRACT (Mon FROM  fecha_cita) = #{month} and EXTRACT(year FROM  fecha_cita) = #{year} order by Estatus;
